import { createStore, useStore } from 'zustand'
import type { NewThread } from './threadStore'
import { GenerationProvider } from '@/generated/graphql'

type Command = { threadId: string | null | NewThread; command: string }
type Generating = { threadId: string | null; generating: boolean }

export type ChatState = 'READY' | 'PENDING' | 'GENERATING'

export type EnabledModels =
	| GenerationProvider.ANTHROPIC_CLAUDE_SONNET_4
	| GenerationProvider.ANTHROPIC_CLAUDE_SONNET_4_5
	| GenerationProvider.FIRST_PARTY_OPENAI_5

export type ChatStore = {
	setSubmittingCommand: (options: Command | null) => void
	setModel: (model: EnabledModels) => void
	setIsGenerating: (isGenerating: Generating) => void
	setCurrentMessageId: (messageId: string | null) => void
	setChatState: (chatState: ChatState) => void
	setLastUserMessageHeight: (lastUserMessageHeight: number) => void
	reset: () => void
	value: {
		preferredGenerationProvider: EnabledModels
		submittingCommand: Command | null
		isGenerating: Map<string | null, boolean> // used for chat stream
		currentMessageId: string | null
		chatState: ChatState
		lastUserMessageHeight: number
	}
}

export const chatStore = createStore<ChatStore>(
	(set): ChatStore => ({
		setModel: (model) =>
			set((state) => ({
				value: { ...state.value, preferredGenerationProvider: model }
			})),
		setSubmittingCommand: (command) =>
			set((state) => ({
				value: { ...state.value, submittingCommand: command }
			})),
		setCurrentMessageId: (messageId) =>
			set((state) => ({
				value: { ...state.value, currentMessageId: messageId }
			})),
		setChatState: (chatState) =>
			set((state) => ({
				value: { ...state.value, chatState }
			})),
		setIsGenerating: (isGenerating) =>
			set((state) => ({
				value: {
					...state.value,
					isGenerating: state.value.isGenerating.set(
						isGenerating.threadId,
						isGenerating.generating
					)
				}
			})),
		setLastUserMessageHeight: (lastUserMessageHeight) =>
			set((state) => ({
				value: { ...state.value, lastUserMessageHeight }
			})),
		reset: () =>
			set({
				value: {
					preferredGenerationProvider:
						GenerationProvider.ANTHROPIC_CLAUDE_SONNET_4,
					submittingCommand: null,
					isGenerating: new Map<string | null, boolean>(),
					currentMessageId: null,
					chatState: 'READY',
					lastUserMessageHeight: 0
				}
			}),
		value: {
			preferredGenerationProvider: GenerationProvider.ANTHROPIC_CLAUDE_SONNET_4,
			submittingCommand: null,
			isGenerating: new Map<string | null, boolean>(),
			currentMessageId: null,
			chatState: 'READY',
			lastUserMessageHeight: 0
		}
	})
)
export const useChatStore = <T>(selector: (state: ChatStore) => T) =>
	useStore(chatStore, selector)
